Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$root='C:\ProgramData\EvoMind';$expectedRemote="C:\SecureInput\hpc-executor-overlay-hotfix-$TransactionId";if([IO.Path]::GetFullPath($RemoteRoot)-cne$expectedRemote){throw 'HPC_EXECUTOR_OVERLAY_REMOTE_ROOT_REJECTED'}
$archive=Join-Path $expectedRemote 'hotfix.zip';$stage=Join-Path $expectedRemote 'hotfix-stage';$resultPath=Join-Path $expectedRemote "transaction-$TransactionId-result.json";$errorPath=Join-Path $expectedRemote "transaction-$TransactionId-error.json";$action='C:\SecureInput\Invoke-ServiceAccountAction.ps1';$seal=Join-Path $root 'bundle\scripts\Seal-Release.ps1';$bundleRuntime=Join-Path $root 'bundle\runtime';$toolsRelative='evomind_runtime/tools.py';$overlayRelative='evomind_runtime/hpc_runtime_overlay.py';$toolsTarget=Join-Path $bundleRuntime 'evomind_runtime\tools.py';$overlayTarget=Join-Path $bundleRuntime 'evomind_runtime\hpc_runtime_overlay.py';$expectedOldTools=$ExpectedOldToolsSha256;$expectedOldOverlay=$ExpectedOldOverlaySha256
function Sha([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()};function Write-Utf8([string]$Path,[object]$Value){[IO.File]::WriteAllText($Path,(($Value|ConvertTo-Json -Depth 12)+"`n"),[Text.UTF8Encoding]::new($false))}
function Tree-Except([string]$Path,[string[]]$Excluded){$full=[IO.Path]::GetFullPath($Path).TrimEnd('\');$rows=@(Get-ChildItem -LiteralPath $full -Recurse -File -Force|ForEach-Object{$relative=$_.FullName.Substring($full.Length).TrimStart('\').Replace('\','/');if($Excluded-notcontains$relative-and$relative-notmatch'(^|/)__pycache__/'-and$relative-notmatch'\.(pyc|pyo)$'){"$relative|$([long]$_.Length)|$(Sha $_.FullName)"}}|Where-Object{$_}|Sort-Object);$hash=[Security.Cryptography.SHA256]::Create();try{$digest=([BitConverter]::ToString($hash.ComputeHash([Text.Encoding]::UTF8.GetBytes(($rows-join"`n"))))).Replace('-','').ToLowerInvariant()}finally{$hash.Dispose()};[ordered]@{file_count=$rows.Count;sha256=$digest}}
