function Assert-Managed([string]$ExpectedBuild){$task=$null;$info=$null;foreach($attempt in 1..10){try{$task=Get-ScheduledTask -TaskPath '\' -TaskName 'EvoMind-Cloud-Node' -ErrorAction Stop;$info=Get-ScheduledTaskInfo -TaskPath '\' -TaskName 'EvoMind-Cloud-Node' -ErrorAction Stop;break}catch{if($attempt-eq10){throw};Start-Sleep -Milliseconds 500}};if([string]$task.State-ne'Ready'-or[int64]$info.LastTaskResult-ne0-or[string]$task.Actions[0].Arguments-notmatch'-Action Start(?:\s|$)'){throw 'HPC_EXECUTOR_OVERLAY_MANAGED_TASK_NOT_READY'};$state=Get-Content -LiteralPath "$root\state\node-processes.json" -Raw -Encoding UTF8|ConvertFrom-Json;foreach($role in @('tenant_enrollment_queue','llm_gateway','python_runtime','web')){$record=@($state.records|Where-Object{[string]$_.role-eq$role});if($record.Count-ne1-or-not(Get-Process -Id ([int]$record[0].pid) -ErrorAction SilentlyContinue)){throw "HPC_EXECUTOR_OVERLAY_ROLE_INVALID:$role"};$owner=Get-CimInstance Win32_Process -Filter "ProcessId=$([int]$record[0].pid)"|Invoke-CimMethod -MethodName GetOwner;if([string]$owner.User-ne'EvoMindSvc'){throw "HPC_EXECUTOR_OVERLAY_OWNER_INVALID:$role"}};$current=Read-Runtime;if([string]$current.runtime.build_id-ne$ExpectedBuild){throw 'HPC_EXECUTOR_OVERLAY_BUILD_MISMATCH'};[ordered]@{build_id=[string]$current.runtime.build_id;roles=4;task_ready=$true;config=$current.config}}
function Read-HpcState{$current=Read-Runtime;$config=$current.config;$bindingPath=Join-Path $root "byoa\tenants\$ExpectedTenantId\hpc-binding.json";$binding=Get-Content -LiteralPath $bindingPath -Raw -Encoding UTF8|ConvertFrom-Json;$expectedProfile="${ExpectedTenantId}_job${ExpectedJobId}_g${ExpectedGeneration}";if([string]$binding.schema-ne'evomind.tenant_hpc_binding.v1'-or[string]$binding.tenant_id-ne$ExpectedTenantId-or[string]$binding.state-ne'active'-or[int]$binding.job_id-ne$ExpectedJobId-or[int]$binding.allocation_generation-ne$ExpectedGeneration-or[string]$binding.credential_profile-ne$expectedProfile){throw 'HPC_EXECUTOR_OVERLAY_BINDING_REJECTED'};$profileInfo=Get-CimInstance Win32_UserProfile -ErrorAction SilentlyContinue|Where-Object{[IO.Path]::GetFileName(([string]$_.LocalPath).TrimEnd('\'))-ieq[string]$config.dedicated_user}|Select-Object -First 1;$serviceHome=if($profileInfo){[string]$profileInfo.LocalPath}else{"C:\Users\$([string]$config.dedicated_user)"};$profileRoot=Join-Path $serviceHome "AppData\Roaming\ResearchAgentWorkstation\profiles\$([string]$binding.credential_profile)";if(-not(Test-Path -LiteralPath $profileRoot -PathType Container)){throw 'HPC_EXECUTOR_OVERLAY_PROFILE_MISSING'};[ordered]@{binding_sha256=Sha $bindingPath;byoa_tree=Tree-Except (Join-Path $root 'byoa') @();profile_root=$profileRoot;profile_tree=Tree-Except $profileRoot @();job_id=[int]$binding.job_id;generation=[int]$binding.allocation_generation;state=[string]$binding.state;credential_profile=[string]$binding.credential_profile}}
function Assert-HpcSame([object]$Before,[object]$After){if($Before.binding_sha256-ne$After.binding_sha256-or$Before.byoa_tree.sha256-ne$After.byoa_tree.sha256-or$Before.byoa_tree.file_count-ne$After.byoa_tree.file_count-or$Before.profile_root-ne$After.profile_root-or$Before.profile_tree.sha256-ne$After.profile_tree.sha256-or$Before.profile_tree.file_count-ne$After.profile_tree.file_count-or$Before.job_id-ne$After.job_id-or$Before.generation-ne$After.generation-or$Before.state-ne$After.state-or$Before.credential_profile-ne$After.credential_profile){throw 'HPC_EXECUTOR_OVERLAY_HPC_STATE_CHANGED'}}
function Wait-Exact([string]$Uri,[string]$Build){$samples=@();$consecutive=0;$deadline=[DateTime]::UtcNow.AddSeconds(180);do{$row=[ordered]@{status_code=0;build_id=$null;exact=$false;elapsed_ms=$null};$sw=[Diagnostics.Stopwatch]::StartNew();try{$response=Invoke-WebRequest -Uri $Uri -UseBasicParsing -TimeoutSec 12;$payload=$response.Content|ConvertFrom-Json;$row.status_code=[int]$response.StatusCode;$row.build_id=[string]$payload.build_id;$row.exact=($row.status_code-eq200-and[bool]$payload.ok-and[string]$payload.status-eq'ready'-and$row.build_id-eq$Build-and@($payload.failures).Count-eq0)}catch{}finally{$sw.Stop();$row.elapsed_ms=[math]::Round($sw.Elapsed.TotalMilliseconds,3)};if($row.exact){$consecutive++}else{$consecutive=0};$samples+=[pscustomobject]$row;if($consecutive-ge3){return [ordered]@{status='ready';samples=@($samples|Select-Object -Last 3)}};Start-Sleep -Seconds 2}while([DateTime]::UtcNow-lt$deadline);throw "HPC_EXECUTOR_OVERLAY_EXACT_HEALTH_TIMEOUT:$Uri"}
function Read-Hotfix{$manifest=Get-Content -LiteralPath (Join-Path $stage 'hpc-executor-overlay-hotfix-manifest.json') -Raw -Encoding UTF8|ConvertFrom-Json;if([string]$manifest.schema-ne'evomind.super_agent_hpc_executor_overlay_hotfix.v1'-or[string]$manifest.build_id-ne$ExpectedBuildId-or[int]$manifest.file_count-ne2-or@($manifest.files).Count-ne2){throw 'HPC_EXECUTOR_OVERLAY_MANIFEST_REJECTED'};$required=@($toolsRelative,$overlayRelative);$declared=@($manifest.files.path);if(@($required|Where-Object{$declared-notcontains$_}).Count-or@($declared|Where-Object{$required-notcontains$_}).Count){throw 'HPC_EXECUTOR_OVERLAY_FILESET_REJECTED'};$actual=@(Get-ChildItem -LiteralPath $stage -Recurse -File -Force|ForEach-Object{$_.FullName.Substring($stage.Length+1).Replace('\','/')});if($actual.Count-ne3-or@($actual|Where-Object{$_-ne'hpc-executor-overlay-hotfix-manifest.json'-and$declared-notcontains$_}).Count){throw 'HPC_EXECUTOR_OVERLAY_ACTUAL_FILESET_REJECTED'};foreach($entry in $manifest.files){$path=Join-Path $stage ([string]$entry.path).Replace('/','\');if(-not(Test-Path -LiteralPath $path -PathType Leaf)-or[long](Get-Item $path).Length-ne[long]$entry.bytes-or(Sha $path)-ne[string]$entry.sha256){throw "HPC_EXECUTOR_OVERLAY_HASH_REJECTED:$($entry.path)"}};$manifest}
if((Test-Path $resultPath)-or(Test-Path $errorPath)){throw 'HPC_EXECUTOR_OVERLAY_RESULT_EXISTS'};$mutex=[Threading.Mutex]::new($false,'Global\EvoMind-Byoa-V12-Deployment');$owned=$false;$backup=$null;$mutated=$false;$serviceStopped=$false;$beforeHpc=$null;$rollbackError=$null
