BuildId;hotfix_sha256=$HotfixSha256;source_manifest_sha256=[string]$manifest.source_manifest_sha256;old_tools_sha256=$expectedOldTools;old_overlay_sha256=$expectedOldOverlay;new_tools_sha256=[string]$toolsEntry.sha256;new_overlay_sha256=[string]$overlayEntry.sha256;other_runtime_tree=$otherBefore;hpc=$beforeHpc});$mutated=$true;Move-Item -LiteralPath $toolsTarget -Destination (Join-Path $backup 'original\moved-bundle-tools.py');Move-Item -LiteralPath $overlayTarget -Destination (Join-Path $backup 'original\moved-bundle-overlay.py');Copy-Item -LiteralPath (Join-Path $stage 'evomind_runtime\tools.py') -Destination $toolsTarget;Copy-Item -LiteralPath (Join-Path $stage 'evomind_runtime\hpc_runtime_overlay.py') -Destination $overlayTarget;$otherAfter=Tree-Except (Join-Path $bundleRuntime 'evomind_runtime') @('tools.py','hpc_runtime_overlay.py');if($otherBefore.sha256-ne$otherAfter.sha256-or$otherBefore.file_count-ne$otherAfter.file_count){throw 'HPC_EXECUTOR_OVERLAY_OTHER_RUNTIME_CHANGED'};if((Sha $toolsTarget)-ne[string]$toolsEntry.sha256-or(Sha $overlayTarget)-ne[string]$overlayEntry.sha256){throw 'HPC_EXECUTOR_OVERLAY_INSTALLED_SHA_REJECTED'};& $seal|Out-Null;Assert-HpcSame $beforeHpc (Read-HpcState);$start=@(& $action -Action Start -TimeoutMinutes 12)|Out-String|ConvertFrom-Json;if([string]$start.status-ne'completed'-or[string]$start.action-ne'Start'){throw 'HPC_EXECUTOR_OVERLAY_START_FAILED'};$serviceStopped=$false;$loopback=Wait-Exact 'http://127.0.0.1:8088/api/healthz' $ExpectedBuildId;$public=Wait-Exact 'https://evomind.zhjjq.tech/api/healthz' $ExpectedBuildId;$afterRuntime=Assert-Managed $ExpectedBuildId;$afterHpc=Read-HpcState;Assert-HpcSame $beforeHpc $afterHpc;if((Sha $toolsTarget)-ne[string]$toolsEntry.sha256-or(Sha $overlayTarget)-ne[string]$overlayEntry.sha256){throw 'HPC_EXECUTOR_OVERLAY_POSTSTART_SHA_REJECTED'};$release=[string]$afterRuntime.config.release_root;$python=Join-Path $release '.venv\Scripts\python.exe';$env:PYTHONPATH=$bundleRuntime+';'+(Join-Path $release 'src');$import=& $python -c "import hashlib,json,evomind_runtime.tools as t,evomind_runtime.hpc_runtime_overlay as h;p=lambda x:hashlib.sha256(open(x,'rb').read()).hexdigest();print(json.dumps({'tools':p(t.__file__),'overlay':p(h.__file__),'tools_path':t.__file__,'overlay_path':h.__file__}))";if($LASTEXITCODE-ne0){throw 'HPC_EXECUTOR_OVERLAY_IMPORT_FAILED'};$identity=$import|Out-String|ConvertFrom-Json;if([string]$identity.tools-ne[string]$toolsEntry.sha256-or[string]$identity.overlay-ne[string]$overlayEntry.sha256){throw 'HPC_EXECUTOR_OVERLAY_IMPORT_IDENTITY_REJECTED'};$payload=[ordered]@{schema='evomind.hpc_executor_overlay_deployment_result.v1';status='installed_and_verified';transaction_id=$TransactionId;build_id=$ExpectedBuildId;hotfix_sha256=$HotfixSha256;source_manifest_sha256=[string]$manifest.source_manifest_sha256;backup_root=$backup;old_tools_sha256=$expectedOldTools;old_overlay_sha256=$expectedOldOverlay;tools_sha256=[string]$toolsEntry.sha256;overlay_sha256=[string]$overlayEntry.sha256;updated_target_count=2;import_identity=$identity;loopback=$loopback;public=$public;runtime=[ordered]@{build_id=[string]$afterRuntime.build_id;roles=[int]$afterRuntime.roles;task_ready=[bool]$afterRuntime.task_ready};hpc_binding_unchanged=$true;byoa_tree_unchanged=$true;profile_unchanged=$true;job_id=$afterHpc.job_id;allocation_generation=$afterHpc.generation;binding_state=$afterHpc.state;secrets_printed=$false;hpc_accessed=$false;gpu_touched=$false;training_started=$false;kaggle_submissions=0};Write-Utf8 $resultPath $payload;$payload|ConvertTo-Json -Depth 12 -Compress
}catch{$failure=$_;$rollback='not_required';if($backup-and$mutated){try{try{$rs=@(& $action -Action Stop -TimeoutMinutes 12)|Out-String|ConvertFrom-Json;if([string]$rs.status-ne'completed'){throw 'HPC_EXECUTOR_OVERLAY_ROLLBACK_STOP_FAILED'};$serviceStopped=$true}catch{$listeners=@(Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue|Where-Object{$_.LocalPort-in@(65068,8765,8088,7890)});if($listeners.Count){throw};$serviceStopped=$true};if(Test-Path -LiteralPath $overlayTarget){Remove-Item -LiteralPath $overlayTarget -Force};if(Test-Path -LiteralPath $toolsTarget){Remove-Item -LiteralPath $toolsTarget -Force};Copy-Item -LiteralPath (Join-Path $backup 'original\bundle-tools.py') -Destination $toolsTarget;Copy-Item -LiteralPath (Join-Path $backup 'original\bundle-overlay.py') -Destination $overlayTarget;& $seal|Out-Null;Assert-HpcSame $beforeHpc (Read-HpcState);$restart=@(& $action -Action Stop -TimeoutMinutes 12)|Out-String|ConvertFrom-Json;$restart=@(& $action -Action Start -TimeoutMinutes 12)|Out-String|ConvertFrom-Json;if([string]$restart.status-ne'completed'){throw 'HPC_EXECUTOR_OVERLAY_ROLLBACK_START_FAILED'};$serviceStopped=$false;Wait-Exact 'http://127.0.0.1:8088/api/healthz' $ExpectedBuildId|Out-Null;Assert-HpcSame $beforeHpc (Read-HpcState);$rollback='restored_and_verified'}catch{$rollback='failed';$rollbackError=[string]$_.Exception.Message}}elseif($serviceStopped){try{$restart=@(& $action -Action Start -TimeoutMinutes 12)|Out-String|ConvertFrom-Json;if([string]$restart.status-eq'completed'){$serviceStopped=$false;$rollback='start_only_recovered'}}catch{}};$errorPayload=[ordered]@{schema='evomind.hpc_executor_overlay_deployment_error.v1';status='failed';transaction_id=$TransactionId;build_id=$ExpectedBuildId;message=[string]$failure.Exception.Message;rollback=$rollback;rollback_error=if($rollbackError){$rollbackError}else{$null};secrets_printed=$false;hpc_accessed=$false;gpu_touched=$false;training_started=$false;kaggle_submissions=0};Write-Utf8 $errorPath $errorPayload;throw}finally{if($owned){try{[void]$mutex.ReleaseMutex()}catch{}};$mutex.Dispose()}
